using System.Collections.Frozen;
using System.Collections.Immutable;
using System.Globalization;
using System.Text;
using System.Text.Json;

namespace PlayMap.Core.Gpu.Programs;

/// <summary>The program table: every product program's name and layout, as data (<c>programs.layout.json</c>, embedded), the one
/// table the GL backend, the Direct3D 12 backend and the HLSL build read. The file is generated by <c>ProgramLayoutTests</c>
/// (PLAYMAP_WRITE_FIXTURES=1) from the GLSL declarations (constants and textures) and from the one mesh layout the passes draw each
/// program with (its vertex inputs, which the vertex shader's declared inputs agree with), and changes only with those sources.
///
/// One instance per device: the product programs hold ids 0…N−1 in the table's order, and each user program the device makes takes
/// the next id past them, never reused while the instance lives. Look-ups (<see cref="Layout"/>, <see cref="Id"/>) take no lock and
/// allocate nothing, from any thread; adding and releasing user programs is serialised.</summary>
public sealed class ProgramTable : IProgramLibrary
{
    /// <summary>The embedded table's resource name.</summary>
    public const string ResourceName = "PlayMap.Core.Gpu.Programs.programs.layout.json";

    private static readonly Lazy<ImmutableArray<ProgramLayout>> Embedded = new(ReadEmbedded);

    private readonly ImmutableArray<ProgramLayout> _product;
    private readonly FrozenDictionary<string, int> _ids;
    private readonly Lock _gate = new();
    private ProgramLayout?[] _user = [];

    /// <summary>A device's table over the embedded product programs.</summary>
    public ProgramTable()
        : this(Product)
    {
    }

    /// <summary>A table over the given product programs (names distinct).</summary>
    public ProgramTable(ImmutableArray<ProgramLayout> product)
    {
        if (product.IsDefault)
            throw new ArgumentException("A table needs its product programs.", nameof(product));
        var ids = new Dictionary<string, int>(StringComparer.Ordinal);
        for (var i = 0; i < product.Length; i++)
        {
            if (!ids.TryAdd(product[i].Name, i))
                throw new ArgumentException($"Two product programs are named '{product[i].Name}'.", nameof(product));
        }
        _product = product;
        _ids = ids.ToFrozenDictionary(StringComparer.Ordinal);
        Names = [.. product.Select(p => p.Name)];
    }

    /// <summary>The embedded product programs, read once.</summary>
    public static ImmutableArray<ProgramLayout> Product => Embedded.Value;

    public IReadOnlyList<string> Names { get; }

    /// <summary>How many product programs the table holds (the first user program's id).</summary>
    public int ProductCount => _product.Length;

    public ProgramId Id(string name) =>
        TryId(name, out var id) ? id : throw new KeyNotFoundException($"No product program is named '{name}'.");

    public bool TryId(string name, out ProgramId id)
    {
        ArgumentNullException.ThrowIfNull(name);
        if (_ids.TryGetValue(name, out var i))
        {
            id = new ProgramId(i);
            return true;
        }
        id = default;
        return false;
    }

    public ProgramLayout Layout(ProgramId id)
    {
        if (id.Value >= 0 && id.Value < _product.Length)
            return _product[id.Value];
        var user = Volatile.Read(ref _user);
        var i = id.Value - _product.Length;
        if (i >= 0 && i < user.Length && user[i] is { } layout)
            return layout;
        throw new ArgumentException(string.Create(CultureInfo.InvariantCulture,
            $"Program {id.Value} is no program of this device (unknown, or a user program already released)."), nameof(id));
    }

    /// <summary>Whether the id is a user program's (made at run time), released or not.</summary>
    public bool IsUser(ProgramId id) => id.Value >= _product.Length;

    /// <summary>Takes a user program's layout; its id is the next past every id handed out before.</summary>
    public ProgramId AddUser(ProgramLayout layout)
    {
        ArgumentNullException.ThrowIfNull(layout);
        lock (_gate)
        {
            var next = new ProgramLayout?[_user.Length + 1];
            Array.Copy(_user, next, _user.Length);
            next[^1] = layout;
            Volatile.Write(ref _user, next);
            return new ProgramId(_product.Length + next.Length - 1);
        }
    }

    /// <summary>Forgets a user program: its id answers no layout again. False for a product program's id, an unknown id or one
    /// already released.</summary>
    public bool ReleaseUser(ProgramId id)
    {
        lock (_gate)
        {
            var i = id.Value - _product.Length;
            if (i < 0 || i >= _user.Length || _user[i] is null)
                return false;
            var next = (ProgramLayout?[])_user.Clone();
            next[i] = null;
            Volatile.Write(ref _user, next);
            return true;
        }
    }

    /// <summary>The table's file for these layouts: UTF-8, two-space indents, "\n" line ends, one constant, texture or vertex input a
    /// line, in the given order. The same layouts write the same bytes.</summary>
    public static string Write(IEnumerable<ProgramLayout> layouts)
    {
        ArgumentNullException.ThrowIfNull(layouts);
        var sb = new StringBuilder();
        sb.Append("{\n  \"programs\": [");
        var firstProgram = true;
        foreach (var p in layouts)
        {
            sb.Append(firstProgram ? "\n" : ",\n");
            firstProgram = false;
            sb.Append("    {\n");
            sb.Append("      \"name\": ").Append(Quote(p.Name)).Append(",\n");
            sb.Append("      \"constantBytes\": ").Append(p.ConstantBytes.ToString(CultureInfo.InvariantCulture)).Append(",\n");
            sb.Append("      \"constants\": [");
            for (var i = 0; i < p.Constants.Length; i++)
            {
                var c = p.Constants[i];
                sb.Append(i == 0 ? "\n" : ",\n");
                sb.Append(CultureInfo.InvariantCulture,
                    $"        {{ \"name\": {Quote(c.Name)}, \"type\": \"{ConstantTypes.Word(c.Type)}\", \"offset\": {c.Offset}, \"count\": {c.Count} }}");
            }
            sb.Append(p.Constants.IsEmpty ? "],\n" : "\n      ],\n");
            sb.Append("      \"textures\": [");
            for (var i = 0; i < p.Textures.Length; i++)
            {
                var t = p.Textures[i];
                sb.Append(i == 0 ? "\n" : ",\n");
                sb.Append(CultureInfo.InvariantCulture,
                    $"        {{ \"name\": {Quote(t.Name)}, \"slot\": {t.Slot}, \"sampled\": {(t.Sampled ? "true" : "false")} }}");
            }
            sb.Append(p.Textures.IsEmpty ? "],\n" : "\n      ],\n");
            sb.Append("      \"inputs\": [");
            for (var i = 0; i < p.Inputs.Length; i++)
            {
                var a = p.Inputs[i];
                sb.Append(i == 0 ? "\n" : ",\n");
                sb.Append(CultureInfo.InvariantCulture,
                    $"        {{ \"location\": {a.Location}, \"components\": {a.Components}, \"offset\": {a.OffsetBytes}, \"stride\": {a.StrideBytes}, \"buffer\": {a.Buffer}, \"divisor\": {a.Divisor} }}");
            }
            sb.Append(p.Inputs.IsEmpty ? "]\n" : "\n      ]\n");
            sb.Append("    }");
        }
        sb.Append(firstProgram ? "]\n}\n" : "\n  ]\n}\n");
        return sb.ToString();
    }

    /// <summary>The layouts a table file holds, in its order. A file that is not the table's shape, a constant type with no word, or
    /// a program named twice is refused with words.</summary>
    public static ImmutableArray<ProgramLayout> Read(string json)
    {
        ArgumentNullException.ThrowIfNull(json);
        using var doc = JsonDocument.Parse(json);
        if (!doc.RootElement.TryGetProperty("programs", out var programs) || programs.ValueKind != JsonValueKind.Array)
            throw new FormatException("The program table holds no \"programs\" list.");
        var names = new HashSet<string>(StringComparer.Ordinal);
        var list = ImmutableArray.CreateBuilder<ProgramLayout>();
        foreach (var p in programs.EnumerateArray())
        {
            var name = p.GetProperty("name").GetString() ?? "";
            if (!names.Add(name))
                throw new FormatException($"The program table names '{name}' twice.");
            var constants = ImmutableArray.CreateBuilder<ConstantSlot>();
            foreach (var c in p.GetProperty("constants").EnumerateArray())
            {
                var word = c.GetProperty("type").GetString() ?? "";
                if (!ConstantTypes.TryParse(word, out var type))
                    throw new FormatException($"Program '{name}': '{word}' is no constant type.");
                constants.Add(new ConstantSlot(c.GetProperty("name").GetString() ?? "", type, c.GetProperty("offset").GetInt32(),
                    c.GetProperty("count").GetInt32()));
            }
            var textures = ImmutableArray.CreateBuilder<TextureSlot>();
            foreach (var t in p.GetProperty("textures").EnumerateArray())
                textures.Add(new TextureSlot(t.GetProperty("name").GetString() ?? "", t.GetProperty("slot").GetInt32(), t.GetProperty("sampled").GetBoolean()));
            var inputs = ImmutableArray.CreateBuilder<VertexAttribute>();
            foreach (var a in p.GetProperty("inputs").EnumerateArray())
                inputs.Add(new VertexAttribute(a.GetProperty("location").GetInt32(), a.GetProperty("components").GetInt32(),
                    a.GetProperty("stride").GetInt32(), a.GetProperty("offset").GetInt32(), a.GetProperty("buffer").GetInt32(),
                    a.GetProperty("divisor").GetInt32()));
            list.Add(new ProgramLayout(name, constants.ToImmutable(), textures.ToImmutable(), p.GetProperty("constantBytes").GetInt32())
            {
                Inputs = inputs.ToImmutable(),
            });
        }
        return list.ToImmutable();
    }

    private static string Quote(string s) => "\"" + JsonEncodedText.Encode(s).Value + "\"";

    private static ImmutableArray<ProgramLayout> ReadEmbedded()
    {
        using var stream = typeof(ProgramTable).Assembly.GetManifestResourceStream(ResourceName)
            ?? throw new InvalidOperationException($"The program table ({ResourceName}) is not embedded in {typeof(ProgramTable).Assembly.GetName().Name}.");
        using var reader = new StreamReader(stream, Encoding.UTF8);
        return Read(reader.ReadToEnd());
    }
}
